        smm={"cite": "Stadtmuseum Meißen, display of the Meissen marks with dates (photographed 2010)", "url": "https://commons.wikimedia.org/wiki/File:Meissner_Marken_im_Stadtmuseum_Mei%C3%9Fen.jpg"},
